export function formatMarkdown(report) {
    const lines = [];
    // Header
    lines.push('# CyberPulse Auditor — Security Report');
    lines.push('');
    lines.push(`**Run ID:** \`${report.runId}\``);
    lines.push(`**Status:** ${report.status}`);
    lines.push(`**Target:** ${report.target}`);
    lines.push(`**Goal:** ${report.goal}`);
    lines.push(`**Iterations:** ${report.iterations}`);
    lines.push(`**Started:** ${report.startedAt}`);
    lines.push(`**Finished:** ${report.finishedAt}`);
    lines.push('');
    // Findings summary
    const open = report.findings.filter((f) => !f.closed);
    const closed = report.findings.filter((f) => f.closed);
    lines.push('## Findings Summary');
    lines.push('');
    lines.push(`| Severity | Count |`);
    lines.push(`|---|---|`);
    lines.push(`| 🟥 Critical | ${report.findings.filter((f) => f.severity === 'critical').length} |`);
    lines.push(`| 🟧 High | ${report.findings.filter((f) => f.severity === 'high').length} |`);
    lines.push(`| 🟨 Medium | ${report.findings.filter((f) => f.severity === 'medium').length} |`);
    lines.push(`| 🟩 Low | ${report.findings.filter((f) => f.severity === 'low').length} |`);
    lines.push('');
    lines.push(`**Open:** ${open.length} | **Closed:** ${closed.length}`);
    lines.push('');
    // Open findings
    if (open.length > 0) {
        lines.push('## Open Findings');
        lines.push('');
        for (const f of open) {
            lines.push(`### [${f.owaspId}] ${f.title} — ${f.severity.toUpperCase()}`);
            lines.push('');
            lines.push(`**ID:** ${f.id}`);
            lines.push('');
            lines.push('**Evidence:**');
            lines.push('```');
            lines.push(f.evidence);
            lines.push('```');
            lines.push('');
            lines.push('**Reproduction:**');
            lines.push(`- Payload: \`${f.repro.payload.slice(0, 100)}\``);
            lines.push(`- Expected: ${f.repro.expected}`);
            lines.push('');
        }
    }
    // Closed findings
    if (closed.length > 0) {
        lines.push('## Closed Findings');
        lines.push('');
        for (const f of closed) {
            lines.push(`- [x] **[${f.owaspId}]** ${f.title} (${f.severity.toUpperCase()}) — closed by ${f.closedBy ?? 'retest'}`);
        }
        lines.push('');
    }
    // Patches
    if (report.patches.length > 0) {
        lines.push('## Remediation Patches');
        lines.push('');
        for (const p of report.patches) {
            const status = p.applied ? '✅ Applied' : '📋 Proposed';
            lines.push(`### ${status}: ${p.kind} patch for ${p.owaspId}`);
            lines.push(`**Finding:** ${p.findingId}`);
            lines.push(`**Rationale:** ${p.rationale}`);
            if (p.requiresRestart)
                lines.push('⚠️ Requires restart');
            lines.push('');
        }
    }
    // Retests
    if (report.retests.length > 0) {
        lines.push('## Retest Results');
        lines.push('');
        for (const r of report.retests) {
            const icon = r.verdict === 'closed' ? '✅' : r.verdict === 'open' ? '❌' : '⚠️';
            lines.push(`${icon} **${r.findingId}**: ${r.verdict} (${r.attemptsCount} attempts)`);
            lines.push(`   ${r.evidence.split('\n')[0] ?? ''}`);
        }
        lines.push('');
    }
    // Footer
    lines.push('---');
    lines.push('*Generated by CyberPulse Auditor*');
    return lines.join('\n');
}
